//! `cargo xtask icons` (MISC-39): renders every committed icon from `packaging/linux/dail.svg`.
//!
//! The outputs are committed and never generated by the build or `cargo xtask verify`: the
//! artwork changes a few times in the life of the project, and `.github/workflows/icons.yml`
//! reruns this when it does. Everything is pure Rust: resvg renders the PNGs, and the ICO and the
//! Windows resource file (`.res`, which the MSVC linker takes as an input, so no `rc.exe` or C
//! toolchain is needed) are written by hand from those PNGs.
//!
//! - `packaging/icons/dail-<n>.png` for [`PNG_SIZES`]: the desktop window icon (app-gui embeds the
//!   256 px one) and the hicolor sizes.
//! - `packaging/windows/dail.ico`: the MSI's Add/Remove Programs icon.
//! - `packaging/windows/dail.res`: the icon resource of `dail.exe` (`app-cli/build.rs`).
//! - `ios/Dail/Assets.xcassets/AppIcon.appiconset/AppIcon-1024.png`: iOS's single-size app icon,
//!   opaque (the App Store refuses an alpha channel; iOS draws its own rounded mask).

use std::path::Path;

use anyhow::{Context, Result, anyhow, bail};
use resvg::{tiny_skia, usvg};

pub(crate) const USAGE: &str = "cargo xtask icons";

const SVG: &str = "packaging/linux/dail.svg";
const PNG_SIZES: &[u32] = &[16, 24, 32, 48, 64, 128, 256, 512];
const ICO_SIZES: &[u32] = &[16, 24, 32, 48, 64, 256];
const IOS_ICON: &str = "ios/Dail/Assets.xcassets/AppIcon.appiconset/AppIcon-1024.png";
/// The SVG's background colour, under the iOS icon's transparent corners.
const IOS_BACKGROUND: (u8, u8, u8) = (0x09, 0x09, 0x0b);

pub(crate) fn run(args: &[String]) -> Result<()> {
    if !args.is_empty() {
        bail!("usage: {USAGE}");
    }
    let root = crate::workspace_root()?;
    let svg = std::fs::read(root.join(SVG)).with_context(|| format!("reading {SVG}"))?;
    let tree = usvg::Tree::from_data(&svg, &usvg::Options::default())
        .with_context(|| format!("parsing {SVG}"))?;

    let mut pngs = Vec::new();
    for &size in PNG_SIZES {
        let png = render(&tree, size, None)?;
        write(&root, &format!("packaging/icons/dail-{size}.png"), &png)?;
        pngs.push((size, png));
    }
    let mut ico_images = Vec::new();
    for &size in ICO_SIZES {
        let png = match pngs.iter().find(|(s, _)| *s == size) {
            Some((_, png)) => png.clone(),
            None => render(&tree, size, None)?,
        };
        ico_images.push((size, png));
    }
    write(&root, "packaging/windows/dail.ico", &ico(&ico_images)?)?;
    write(&root, "packaging/windows/dail.res", &res(&ico_images)?)?;
    write(&root, IOS_ICON, &render(&tree, 1024, Some(IOS_BACKGROUND))?)?;
    Ok(())
}

fn write(root: &Path, relative: &str, bytes: &[u8]) -> Result<()> {
    let path = root.join(relative);
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(&path, bytes).with_context(|| format!("writing {relative}"))?;
    let mut out = std::io::stdout().lock();
    std::io::Write::write_fmt(&mut out, format_args!("wrote {relative}\n"))?;
    Ok(())
}

/// `tree` as a `size`×`size` PNG, over `background` if given (then opaque).
fn render(tree: &usvg::Tree, size: u32, background: Option<(u8, u8, u8)>) -> Result<Vec<u8>> {
    let mut pixmap =
        tiny_skia::Pixmap::new(size, size).ok_or_else(|| anyhow!("empty {size} px pixmap"))?;
    if let Some((r, g, b)) = background {
        pixmap.fill(tiny_skia::Color::from_rgba8(r, g, b, 255));
    }
    let view = tree.size();
    let transform =
        tiny_skia::Transform::from_scale(size as f32 / view.width(), size as f32 / view.height());
    resvg::render(tree, transform, &mut pixmap.as_mut());
    if background.is_none() {
        return pixmap
            .encode_png()
            .with_context(|| format!("encoding the {size} px PNG"));
    }
    // Opaque: drop the alpha channel (premultiplied colour equals straight colour at alpha 255).
    let rgb: Vec<u8> = pixmap
        .data()
        .as_chunks::<4>()
        .0
        .iter()
        .flat_map(|px| [px[0], px[1], px[2]])
        .collect();
    let mut out = Vec::new();
    let mut encoder = png::Encoder::new(&mut out, size, size);
    encoder.set_color(png::ColorType::Rgb);
    encoder.set_depth(png::BitDepth::Eight);
    let mut writer = encoder.write_header()?;
    writer.write_image_data(&rgb)?;
    writer.finish()?;
    Ok(out)
}

/// The width/height byte of an icon directory entry: 0 means 256.
fn dimension_byte(size: u32) -> Result<u8> {
    match size {
        256 => Ok(0),
        1..=255 => Ok(size as u8),
        _ => bail!("an icon cannot be {size} px"),
    }
}

fn len_u32(bytes: &[u8]) -> Result<u32> {
    u32::try_from(bytes.len()).context("icon image too large")
}

/// An ICO file with PNG-compressed images (Windows Vista and later).
pub(crate) fn ico(images: &[(u32, Vec<u8>)]) -> Result<Vec<u8>> {
    let count = u16::try_from(images.len())?;
    let mut out = Vec::new();
    out.extend_from_slice(&[0, 0, 1, 0]);
    out.extend_from_slice(&count.to_le_bytes());
    let mut offset = 6 + 16 * u32::from(count);
    for (size, png) in images {
        let d = dimension_byte(*size)?;
        out.extend_from_slice(&[d, d, 0, 0]);
        out.extend_from_slice(&1u16.to_le_bytes()); // planes
        out.extend_from_slice(&32u16.to_le_bytes()); // bits per pixel
        out.extend_from_slice(&len_u32(png)?.to_le_bytes());
        out.extend_from_slice(&offset.to_le_bytes());
        offset += len_u32(png)?;
    }
    for (_, png) in images {
        out.extend_from_slice(png);
    }
    Ok(out)
}

const RT_ICON: u16 = 3;
const RT_GROUP_ICON: u16 = 14;
const LANG_EN_US: u16 = 0x0409;

/// One resource of a `.res` file with a numeric type and name, padded to a 4-byte boundary.
fn res_entry(out: &mut Vec<u8>, kind: u16, name: u16, flags: u16, data: &[u8]) -> Result<()> {
    out.extend_from_slice(&len_u32(data)?.to_le_bytes());
    out.extend_from_slice(&32u32.to_le_bytes()); // header size
    out.extend_from_slice(&[0xff, 0xff]);
    out.extend_from_slice(&kind.to_le_bytes());
    out.extend_from_slice(&[0xff, 0xff]);
    out.extend_from_slice(&name.to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes()); // data version
    out.extend_from_slice(&flags.to_le_bytes());
    out.extend_from_slice(&LANG_EN_US.to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes()); // version
    out.extend_from_slice(&0u32.to_le_bytes()); // characteristics
    out.extend_from_slice(data);
    while !out.len().is_multiple_of(4) {
        out.push(0);
    }
    Ok(())
}

/// A Win32 `.res` file holding `images` as icon group 1, the one Explorer shows for the
/// executable. What `rc.exe` writes for `1 ICON "dail.ico"`.
pub(crate) fn res(images: &[(u32, Vec<u8>)]) -> Result<Vec<u8>> {
    let count = u16::try_from(images.len())?;
    let mut out = Vec::new();
    // The empty resource every .res file starts with.
    out.extend_from_slice(&0u32.to_le_bytes());
    out.extend_from_slice(&32u32.to_le_bytes());
    out.extend_from_slice(&[0xff, 0xff, 0, 0, 0xff, 0xff, 0, 0]);
    out.extend_from_slice(&[0; 16]);
    let mut group = vec![0, 0, 1, 0];
    group.extend_from_slice(&count.to_le_bytes());
    for (index, (size, png)) in images.iter().enumerate() {
        let id = u16::try_from(index + 1)?;
        res_entry(&mut out, RT_ICON, id, 0x1010, png)?;
        let d = dimension_byte(*size)?;
        group.extend_from_slice(&[d, d, 0, 0]);
        group.extend_from_slice(&1u16.to_le_bytes());
        group.extend_from_slice(&32u16.to_le_bytes());
        group.extend_from_slice(&len_u32(png)?.to_le_bytes());
        group.extend_from_slice(&id.to_le_bytes());
    }
    res_entry(&mut out, RT_GROUP_ICON, 1, 0x1030, &group)?;
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn word(bytes: &[u8], at: usize) -> u16 {
        u16::from_le_bytes([bytes[at], bytes[at + 1]])
    }
    fn dword(bytes: &[u8], at: usize) -> u32 {
        u32::from_le_bytes([bytes[at], bytes[at + 1], bytes[at + 2], bytes[at + 3]])
    }

    #[test]
    fn ico_points_at_each_image() {
        let images = vec![(16, vec![1, 2, 3]), (256, vec![4, 5])];
        let ico = ico(&images).unwrap();
        assert_eq!(word(&ico, 2), 1);
        assert_eq!(word(&ico, 4), 2);
        assert_eq!((ico[6], ico[22]), (16, 0));
        let second = dword(&ico, 22 + 12) as usize;
        assert_eq!(&ico[second..], &[4, 5]);
        assert_eq!(dword(&ico, 6 + 12) as usize, 6 + 32);
    }

    #[test]
    fn res_has_the_null_entry_then_icons_then_the_group() {
        let images = vec![(32, vec![9; 5]), (48, vec![7; 8])];
        let res = res(&images).unwrap();
        assert_eq!((dword(&res, 0), dword(&res, 4)), (0, 32));
        // First icon: 5 bytes of data, type 3, name 1, padded to 40 bytes.
        assert_eq!(dword(&res, 32), 5);
        assert_eq!((word(&res, 42), word(&res, 46)), (RT_ICON, 1));
        let second = 32 + 32 + 8;
        assert_eq!(word(&res, second + 14), 2);
        let group = second + 32 + 8;
        assert_eq!(word(&res, group + 10), RT_GROUP_ICON);
        assert_eq!(dword(&res, group), 6 + 14 * 2);
        assert!(res.len().is_multiple_of(4));
    }

    #[test]
    fn dimension_of_256_is_zero() {
        assert_eq!(dimension_byte(256).unwrap(), 0);
        assert!(dimension_byte(512).is_err());
    }
}
